'use strict';
const $=id=>document.getElementById(id), panel=$('panel'), open=$('open');
function reportSize(){if(!panel.hidden)parent.postMessage({terraHeight:Math.ceil(panel.getBoundingClientRect().height)+16},location.origin)}
new ResizeObserver(reportSize).observe(panel);
open.onclick=()=>{panel.hidden=false;parent.postMessage({terraPanel:true}, location.origin);reportSize();open.setAttribute('aria-expanded','true');$('close').focus()};
function closePanel(){panel.hidden=true;parent.postMessage({terraPanel:false}, location.origin);open.setAttribute('aria-expanded','false');open.focus()} $('close').onclick=closePanel;
window.addEventListener('message',e=>{if(e.origin===location.origin && e.source===parent && e.data?.terraOpen===true)open.click()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)closePanel()});
$('chatTab').onclick=()=>{$('chat').hidden=false;$('private').hidden=true};$('privateTab').onclick=()=>{$('private').hidden=false;$('chat').hidden=true};
let token=null,user=null,preference='';
function message(s){const p=document.createElement('p');p.className='bubble';p.textContent=s;$('messages').append(p);p.scrollIntoView({block:'nearest'})}
function answer(q){message('Tú: '+q);let response,url;if(/huerto/i.test(q)){response='Empieza observando la luz y el espacio disponible. Nuestra guía recoge los primeros pasos para cultivar en casa.';url='/universo/huerto-urbano.html'}else if(/romero|planta|aromática/i.test(q)){response='El romero es una planta aromática. Puedes conocer sus cuidados básicos y fuentes en nuestra ficha.';url='/universo/romero.html'}else if(/pausa|medit|relajar|respir/i.test(q)){response='Puedes probar una pausa breve y escuchar a tu ritmo. Hemos preparado una guía para empezar.';url='/universo/meditacion-principiantes.html'}else if(/polin|abejas/i.test(q)){response='Descubre el papel de los polinizadores en la web.';url='/polinizadores.html'}else{response='Estoy en pruebas y todavía no puedo responder preguntas abiertas. Prueba una de las preguntas sugeridas.'}if(preference)response+=' Tu preferencia guardada es '+preference+'.';message('TERRA: '+response);if(url){const a=document.createElement('a');a.className='answer-link';a.href=url;a.target='_top';a.textContent='Leer la guía';$('messages').append(a)}reportSize()}
$('chatForm').onsubmit=e=>{e.preventDefault();const q=$('question').value.trim();if(!q)return;$('question').value='';answer(q)};
document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>answer(b.dataset.question)));
const cfg=window.TERRA_CONFIG, configured=!!(cfg.supabaseUrl&&cfg.supabaseAnonKey);
if(configured)$('status').textContent='Accede con tu cuenta de prueba.';
async function api(path,options={}){if(!configured)throw Error('Supabase no está configurado.');const res=await fetch(cfg.supabaseUrl.replace(/\/$/,'')+path,{...options,headers:{apikey:cfg.supabaseAnonKey,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...(options.headers||{})}});let data=null;try{data=await res.json()}catch{}if(!res.ok)throw Error(data?.msg||data?.message||data?.error_description||'No se pudo completar la operación.');return data}
async function run(fn){try{await fn()}catch(e){$('status').textContent=e.message}}
async function enter(){ $('auth').hidden=true;$('account').hidden=false;$('identity').textContent='Sesión iniciada';$('status').textContent='Espacio privado de prueba';const rows=await api('/rest/v1/terra_memory?select=preference');preference=rows?.[0]?.preference||'';$('remember').checked=!!rows?.length;$('preference').value=preference; }
$('login').onclick=()=>run(async()=>{const data=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:$('email').value,password:$('password').value})});token=data.access_token;user=data.user;$('password').value='';await enter()});
$('signup').onclick=()=>run(async()=>{await api('/auth/v1/signup',{method:'POST',body:JSON.stringify({email:$('email').value,password:$('password').value})});$('password').value='';$('status').textContent='Revisa tu correo si el proyecto exige confirmación y después inicia sesión.'});
$('save').onclick=()=>run(async()=>{if(!$('remember').checked){$('status').textContent='Activa la opción para guardar, o usa Borrar memoria.';return}await api('/rest/v1/terra_memory?on_conflict=user_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:user.id,preference:$('preference').value})});preference=$('preference').value;$('status').textContent='Preferencia guardada.'});
$('erase').onclick=()=>run(async()=>{await api('/rest/v1/terra_memory?user_id=eq.'+encodeURIComponent(user.id),{method:'DELETE'});preference='';$('preference').value='';$('remember').checked=false;$('status').textContent='Memoria borrada.'});
$('logout').onclick=()=>run(async()=>{try{await api('/auth/v1/logout',{method:'POST'})}finally{token=null;user=null;preference='';$('account').hidden=true;$('auth').hidden=false;$('status').textContent='Sesión cerrada.'}});
